using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Settings;[Authorize]public sealed class AuditModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public IReadOnlyList<AuditLog> Events{get;private set;}=[];public async Task<IActionResult> OnGetAsync(CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();Events=await db.AuditLogs.AsNoTracking().Where(x=>x.AccountId==current.AccountId&&!x.IsDeleted).OrderByDescending(x=>x.CreatedAt).Take(200).ToListAsync(ct);return Page();}}
